mapper.update:
UPDATE storybooks
SET is_public = CASE WHEN #{isPublic} = true THEN 'Y' ELSE 'N' END
WHERE id = #{storyId}

mapper.select:
SELECT id AS storyId, plan_id AS planId, title, DATE_FORMAT(created_at, '%Y-%m-%d') AS createdDate, thumbnail_path AS thumbnailPath, CASE WHEN is_public = 'Y' THEN true ELSE false END AS isPublic FROM storybooks WHERE member_id = #{memberId}
AND plan_id = #{planId}
ORDER BY created_at DESC
